"use client";

import { Surface, bounded, number } from "./_shared";
import type { SurfaceProps } from "./_shared";
export interface ContextSegment {
  id: string;
  label: string;
  tokens: number;
}
export interface ContextWindowProps extends SurfaceProps {
  segments: ContextSegment[];
  capacity: number;
  reserved?: number;
}
export function ContextWindow({
  segments,
  capacity,
  reserved = 0,
  ...props
}: ContextWindowProps) {
  const total = segments.reduce((sum, s) => sum + Math.max(0, s.tokens), 0);
  const limit = Number.isFinite(capacity) && capacity > 0 ? capacity : 1;
  const percent = bounded((total / limit) * 100, 100);
  return (
    <Surface
      {...props}
      title="Context window"
      eyebrow="Model input"
      actions={
        <span className="ac-mono ac-muted">{number(percent)}% used</span>
      }
    >
      <div
        className="ac-context-meter"
        role="meter"
        aria-label="Context tokens used"
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={bounded(total, limit)}
        aria-valuetext={`${number(total)} of ${number(limit)} tokens`}
      >
        {segments.map((s, i) => (
          <span
            key={s.id}
            className="ac-segment"
            style={{
              width: `${(Math.max(0, s.tokens) / Math.max(limit, total)) * 100}%`,
              opacity: 1 - (i % 5) * 0.15,
            }}
          />
        ))}
      </div>
      <ul className="ac-list">
        {segments.map((s) => (
          <li className="ac-row" key={s.id}>
            <span>{s.label}</span>
            <span className="ac-mono ac-muted">
              {number(Math.max(0, s.tokens))}
            </span>
          </li>
        ))}
      </ul>
      <footer className="ac-footer ac-muted">
        {number(total)} / {number(limit)} tokens ·{" "}
        {number(Math.max(0, limit - total - reserved))} available
        {reserved > 0 && ` · ${number(reserved)} reserved`}
      </footer>
      {total + reserved > limit && (
        <p className="ac-error" role="status">
          Context exceeds the available budget. Remove or summarize inputs.
        </p>
      )}
    </Surface>
  );
}

"use client";

import { useRef, useState } from "react";
import type { HTMLAttributes, ReactNode } from "react";

export type RunStatus =
  "queued" | "running" | "paused" | "completed" | "failed" | "cancelled";
export type SurfaceProps = HTMLAttributes<HTMLElement>;
export const cx = (...values: (string | undefined | false)[]) =>
  values.filter(Boolean).join(" ");
export const number = (value: number) =>
  new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value);
export const bounded = (value: number, max: number) =>
  Math.max(0, Math.min(Number.isFinite(value) ? value : 0, max));
export function safeHref(href: string) {
  try {
    const url = new URL(href);
    return ["http:", "https:"].includes(url.protocol) ? url.href : undefined;
  } catch {
    return undefined;
  }
}
export function Status({ value }: { value: RunStatus }) {
  return (
    <span className="ac-status" data-status={value}>
      <span aria-hidden="true" className="ac-dot" />
      {value}
    </span>
  );
}
export function Surface({
  title,
  eyebrow,
  actions,
  children,
  className,
  ...props
}: SurfaceProps & { title: string; eyebrow?: string; actions?: ReactNode }) {
  return (
    <section
      {...props}
      className={cx("ac-surface", className)}
      aria-label={props["aria-label"] ?? title}
    >
      <header className="ac-header">
        <div>
          {eyebrow && <span className="ac-eyebrow">{eyebrow}</span>}
          <h3 className="ac-title">{title}</h3>
        </div>
        {actions}
      </header>
      {children}
    </section>
  );
}
export function JsonView({ value, label }: { value: unknown; label: string }) {
  let content: string;
  try {
    content = JSON.stringify(value, null, 2) ?? "No value";
  } catch {
    content = "Value cannot be serialized";
  }
  return (
    <pre className="ac-code" aria-label={label}>
      <code>{content}</code>
    </pre>
  );
}
/** Serializes actions immediately, including before React has rendered a pending state. */
export function useAction() {
  const lock = useRef(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();
  const run = async (action: () => void | Promise<void>) => {
    if (lock.current) return;
    lock.current = true;
    setPending(true);
    setError(undefined);
    try {
      await action();
    } catch (cause) {
      setError(
        cause instanceof Error
          ? cause.message
          : "Something went wrong. Please try again.",
      );
    } finally {
      lock.current = false;
      setPending(false);
    }
  };
  return { pending, error, run };
}

