  color: var(--ac-accent);
  font-size: 18px;
}
.ac-stream[data-status="streaming"] .ac-stream-indicator,
.ac-stream[data-status="connecting"] .ac-stream-indicator {
  animation: ac-spin 5s linear infinite;
}
.ac-stream[data-status="error"] .ac-stream-indicator {
  color: var(--ac-danger);
}
.ac-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@keyframes ac-pulse {
  50% {
    opacity: 0.35;
  }
}
@keyframes ac-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ac-status .ac-dot,
  .ac-stream .ac-stream-indicator {
    animation: none !important;
  }
}
@media (max-width: 480px) {
  .ac-header {
    align-items: flex-start;
  }
  .ac-composer-footer {
    flex-wrap: wrap;
  }
  .ac-handoff > span:first-child,
  .ac-handoff > span:last-child {
    padding: 8px;
  }
  .ac-metrics dd {
    font-size: 18px;
  }
}
